5	const isBlob = (b: any): b is Blob => b instanceof Blob
6	
7	/**
8	 * Processes the response body of an HTTP request.
9	 * Extracts MIME type, attachment filename, and generates a data URL.
10	 */
11	export function processResponseBody({ data, headers }: { data: unknown; headers: { name: string; value: string }[] }) {
12	  const contentType = headers.find((header) => header.name.toLowerCase() === 'content-type')
13	  const mimeType = contentType?.value ? parseMimeType(contentType.value) : undefined
14	  const attachmentFilename = extractFilename(
15	    headers.find((header) => header.name.toLowerCase() === 'content-disposition')?.value ?? '',
16	  )
17	
18	  const dataUrl = (() => {
19	    if (isBlob(data)) {
20	      return URL.createObjectURL(data)
21	    }
22	    if (typeof data === 'string') {
23	      return URL.createObjectURL(new Blob([data], { type: mimeType ? mimeType.toString() : undefined }))
24	    }
25	    if (data instanceof Object && Object.keys(data).length) {
26	      return URL.createObjectURL(
27	        new Blob([JSON.stringify(data)], {
28	          type: mimeType ? mimeType.toString() : undefined,
29	        }),
30	      )
31	    }
32	    return ''
33	  })()
34	
35	  return { mimeType, attachmentFilename, dataUrl }
36	}
