/**
 * Converts a MIME type glob pattern into a case-insensitive regular expression.
 *
 * All regex-significant characters are escaped so only the '*' wildcard remains
 * meaningful, letting patterns such as 'application/vnd.*+json' match
 * 'application/vnd.api+json'.
 */
const patternToRegExp = (pattern: string): RegExp => {
  const escaped = pattern.replace(/[|\\{}()[\]^$+?.]/g, '\\$&').replace(/\*/g, '.*')
  return new RegExp(`^${escaped}$`, 'i')
}

/**
 * Finds the first plugin response body handler that matches the given MIME type.
 *
 * Plugins without a responseBody property are skipped. Matching is case-insensitive
 * and each handler may declare multiple MIME type patterns, which support '*' wildcards.
 *
 * @returns The matching handler, or undefined when none is found.
 */
export const resolveResponseBodyHandler = (
  mimeType: string,
  plugins: ClientPlugin[],
): ResponseBodyHandler | undefined => {
  for (const plugin of plugins) {
    if (!plugin.responseBody) {
      continue
    }

    for (const handler of plugin.responseBody) {
      if (handler.mimeTypes.some((pattern) => patternToRegExp(pattern).test(mimeType))) {
        return handler
      }
    }
  }

  return undefined
}
